text:
/* 작업 화면과 구조도의 세부 양식. */
.eyebrow {
  display: none;
}
.pageintro h1 {
  font-size: 23px;
  letter-spacing: -0.6px;
}
.pageintro p:not(.eyebrow) {
  font-size: 13px;
}
.mainnav button {
  font-size: 12px;
}
.treeheading {
  font-size: 12px;
}
.filetree button {
  font-size: 12px;
}
.history button {
  font-size: 12px;
}
.quiet,
.secondary,
.primary {
  font-size: 12px;
}
#closeDetail {
  display: inline-grid !important;
}
.detailhead h2 {
  font-size: 18px;
}
.detailhead p {
  font-size: 12px;
  line-height: 1.75;
}
.detailtabs button {
  font-size: 12px;
}
.evidence-kind {
  display: inline-block;
  border-radius: 2px;
  padding: 3px 6px;
  margin-left: 5px;
  font-size: 12px;
  color: #393b33;
  background: #f5f5f4;
}
.evidence-kind:empty,
.decision-kind:empty,
.decision-note:empty {
  display: none;
}
.decision-kind {
  display: inline-block;
  border-radius: 2px;
  padding: 3px 6px;
  margin-left: 5px;
  font-size: 12px;
  font-weight: 600;
  color: #52564a;
  background: #f2f2f1;
}
.decision-kind[data-owner="model"] {
  color: #3f4239;
  background: #f4f4f3;
}
.decision-kind[data-owner="config"] {
  color: #715429;
  background: #f9f2e4;
}
.decision-kind[data-owner="user"] {
  color: #356556;
  background: #eaf4f0;
}
.decision-kind[data-owner="runtime"] {
  color: #3d4038;
  background: #f3f3f2;
}
.decision-kind[data-owner="external"] {
  color: #64695b;
  background: #f3f3f2;
}
.detailhead .decision-note {
  font-size: 12px;
  line-height: 1.7;
  color: #63685a;
  margin-top: 3px;
}
.decisionsummary {
  font-size: 12px;
  line-height: 1.8;
  margin: 0 0 8px;
}
.decisionsummary button {
  margin-left: 8px;
}
.decisionmap {
  display: grid;
  grid-template-columns: 74px 1fr;
  gap: 4px 8px;
  margin: 6px 0;
  font-size: 12px;
  line-height: 1.6;
}
.decisionmap dt {
  color: #63685a;
}
.decisionmap dd {
  margin: 0;
}
.evidence-kind[data-evidence="diagnostic"] {
  color: #796232;
  background: #fcf6e8;
}
.evidence-kind[data-evidence="missing"] {
  color: #846060;
  background: #faf0f0;
}
.inputlinks {
  margin: 0 20px 8px;
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}
.inputlinks small {
  color: #63685a;
  font-size: 12px;
}
.inspection-link {
  padding: 4px 7px;
  font-size: 12px;
  border: 1px solid #dcded9;
  background: #f9f9f9;
  border-radius: 2px;
  color: #393b34;
  text-align: left;
  overflow-wrap: anywhere;
}
.inspection-link:hover {
  border-color: #565a4e;
  background: #f5f5f4;
}
.input-snapshot > header {
  display: grid;
  gap: 5px;
}
.input-snapshot > header strong {
  font-size: 15px;
}
.input-snapshot > header span {
  color: #63685a;
  font-size: 12px;
}
.input-navigation {
  display: flex;
  gap: 5px;
  margin: 10px 0;
  flex-wrap: wrap;
}
.input-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 5px;
  margin: 12px 0 7px;
}
.input-stats span {
  display: grid;
  gap: 5px;
  background: #f8f8f7;
  padding: 8px 5px;
  text-align: center;
  font-size: 12px;
  color: #63685a;
  border-radius: 2px;
}
.input-stats b {
  font: 15px var(--mono);
  color: #53574b;
}
.input-audit {
  padding: 6px 0 10px;
  color: #63685a;
  font-size: 12px;
}
.input-diff {
  padding: 9px;
  background: #fbfbfa;
  border: 1px solid #e3e4e0;
  border-radius: 2px;
  margin-bottom: 16px;
}
.input-diff > summary,
.input-tools > summary {
  cursor: pointer;
  color: #353831;
  font-size: 12px;
}
.input-diff .note {
  font-size: 12px;
}
.input-diff-counts {
  display: flex;
  gap: 10px;
  padding: 4px 0 8px;
  color: #63685a;
  font-size: 12px;
}
.input-change {
  padding: 6px 0;
  border-top: 1px solid #e9eae6;
}
.input-change > summary {
  display: flex;
  gap: 9px;
  cursor: pointer;
  font-size: 12px;
}
.change-added {
  color: #2d785b;
}
.change-removed {
  color: #9c5c5c;
}
.change-changed {
  color: #715429;
}
.input-message {
  border: 1px solid #e4e5e2;
  border-radius: 2px;
  margin: 8px 0;
  padding: 9px;
}
.input-message > summary {
  display: flex;
  gap: 10px;
  cursor: pointer;
  font-size: 12px;
  align-items: center;
}
.input-message > summary code {
  color: #63685a;
  font-size: 12px;
}
.input-message > summary span {
  margin-left: auto;
  font-size: 12px;
  color: #63685a;
}
.input-message[open] > summary {
  margin-bottom: 10px;
}
.message-labels {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-bottom: 8px;
}
.message-labels span {
  font-size: 12px;
  background: #f3f4f2;
  color: #63685a;
  padding: 2px 5px;
  border-radius: 2px;
}
.input-origins {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding-top: 8px;
}
.input-origins > small {
  font-size: 12px;
  color: #63685a;
}
.input-tools {
  padding: 10px 0;
}
.input-snapshot h3 {
  margin-top: 18px;
  font-size: 13px;
}
.input-empty p {
  font-size: 12px;
  line-height: 1.8;
  color: #63685a;
}
.input-view .detailhead {
  padding-top: 10px;
  padding-bottom: 8px;
}
.input-view .detailhead h2 {
  font-size: 16px;
  margin: 8px 0;
}
.input-view #componentNavigator {
  display: none;
}
.input-view .detailtabs {
  margin-top: 0;
}
.message-fragment {
  margin: 6px 0;
  padding: 6px;
  border-left: 2px solid #d0d2cc;
  background: #fcfcfb;
}
.message-fragment > summary,
.message-json > summary {
  color: #63685a;
  font-size: 12px;
  cursor: pointer;
}
.message-fragment .valuebox {
  margin-bottom: 0;
}
.message-json {
  margin-top: 10px;
}
.datalabel {
  font-size: 12px;
}
.databox pre {
  font-size: 12px;
}
.codeline {
  font-size: 12px;
}
.sourcepeek {
  font-size: 12px;
}
.activitybar strong {
  white-space: nowrap;
}
.activitybar button {
  background: var(--paper);
  border: 1px solid #d2c5a6;
  border-radius: 2px;
  padding: 4px 11px;
  white-space: nowrap;
}
.activity-prompt {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
}
.activity-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #957738;
}
#journeyView .pageintro {
  display: none;
}
#journeyView .samplebanner {
  padding: 7px 12px;
  margin: 0;
  min-height: 29px;
  font-size: 12px;
  border-radius: 2px;
}
#journeyView .samplebanner p,
#journeyView .samplebanner small {
  display: none;
}
#journeyView .requestsummary {
  margin: 0;
  padding: 8px 12px;
  border-radius: 2px;
  background: var(--paper);
  box-shadow: none;
}
#journeyView .requestsummary p {
  font-size: 12px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin: 2px 0;
  line-height: 1.6;
}
#journeyView .requestsummary header {
  margin: 0;
}
#journeyView .requestsummary small {
  font-size: 12px;
  margin-top: 0;
}
#journeyView.focus .execution > .sectionbar {
  margin-bottom: 0;
}
#journeyView.focus .requestsummary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: 20px auto;
  padding: 6px 12px;
}
#journeyView.focus .requestsummary header {
  display: contents;
}
#journeyView.focus .requestsummary header > span {
  display: none;
}
#journeyView.focus .requestsummary button {
  grid-column: 2;
  grid-row: 1 / 3;
}
#journeyView.focus .requestsummary p {
  grid-column: 1;
  grid-row: 1;
  margin: 0;
}
#journeyView.focus .requestsummary small {
  grid-column: 1;
  grid-row: 2;
  /* 11px 글자에서 한 줄에 다 들어가지 않으면 다음 행(전체 구조 헤더)을 덮지 않도록 줄임표로 자른다 */
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.5;
}
.has-activity .execution .controls {
  display: none;
}
#journeyView .composer {
  padding: 10px 12px;
  border-radius: 2px;
  box-shadow: none;
}
#journeyView .composer textarea {
  font-size: 13px;
  min-height: 45px;
  height: 45px;
  padding: 5px 0;
  resize: none;
}
#journeyView .modebar {
  margin: 0;
  float: right;
  gap: 8px;
}
#journeyView .modebar select {
  padding: 4px 6px;
  font-size: 12px;
}
#journeyView #modeNote {
  display: none;
}
#journeyView .draftinfo {
  position: absolute;
  left: 14px;
  bottom: 0;
  margin: 0;
}
#journeyView .composer-bottom {
  padding-top: 6px;
  border: 0;
}
#journeyView .examples {
  padding: 0;
  margin: 0;
  gap: 4px;
  flex-wrap: wrap;
}
#journeyView .examples button {
  padding: 4px 7px;
  border-radius: 2px;
  font-size: 12px;
}
#journeyView .configuration {
  margin: 0;
  border-radius: 2px;
}
#journeyView .configuration summary {
  padding: 7px 11px;
}
.configbody p,
.configbody .check {
  font-size: 12px;
}
.configbody .field {
  font-size: 12px;
}
#showAnswer.ready {
  color: var(--ink);
  font-weight: 650;
}
.diagram-caption > span:first-child {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.componentnav {
  margin: 0 20px 8px;
  display: grid;
  gap: 5px;
}
.componentnav label {
  font-size: 12px;
  color: #63685a;
}
.componentnav select {
  width: 100%;
  padding: 6px;
  border: 1px solid #dddeda;
  border-radius: 2px;
  font-size: 12px;
  background: #fcfcfb;
  color: #30322b;
}
.stepheading {
  display: flex;
  gap: 10px;
  align-items: center;
  min-height: 23px;
}
.stepheading strong {
  font-size: 12px;
}
.stepheading .quiet {
  margin-left: auto;
  font-size: 12px;
}
.stepnumber {
  font: 11px var(--mono);
  color: #63685a;
}
.steptransfer {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 20px minmax(0, 1fr);
  gap: 10px;
  margin-top: 4px;
  font-size: 12px;
  align-items: center;
}
.steptransfer > div {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.steptransfer small {
  color: #63685a;
  flex-shrink: 0;
  font-size: 12px;
}
.steptransfer span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--mono);
  color: #5c6054;
}
.steptransfer b {
  color: #45483f;
  font-weight: 400;
}.controls button {
  padding: 4px 9px;
  font-size: 12px;
}
.diagram-layout #route,
.diagram-layout #connections,
.diagram-layout #agentPanel,
.diagram-layout #contextComposition,
.diagram-layout #planPanel,
.diagram-layout #answerPanel {
  display: none !important;
}
.recordtray .eventtoolbar {
  margin: 0;
  padding: 7px 10px;
  background: #fafaf9;
  position: sticky;
  top: 0;
  z-index: 2;
}
.recordtray .event {
  min-height: 42px;
}
.recordtray .eventtitle {
  font-size: 12px;
}
.recordtray .eventsub,
.recordtray .eventid {
  font-size: 12px;
}
.recordtray .chapter > summary {
  font-size: 12px;
}
.recordtray #timeline {
  max-height: none;
  padding: 0 8px 8px;
}
.answer-readout {
  white-space: pre-wrap;
  line-height: 1.8;
  font-size: 13px;
}
.memory-session {
  display: flex;
  gap: 14px;
  align-items: center;
  padding: 4px 0 9px;
  font-size: 12px;
}
#memoryView .pageintro {
  margin: 4px 0 12px;
}
#memoryView .pageintro h1 {
  margin: 0;
  font-size: 22px;
}
#memoryView .pageintro p {
  margin: 5px 0;
}
.memory-session > span {
  color: #63685a;
  flex: 1;
}
.memory-session code {
  font-size: 12px;
}
.memory-check {
  background: var(--paper);
  border: 1px solid #dedfdb;
  border-radius: 2px;
  padding: 8px 12px;
  display: flex;
  gap: 12px;
  align-items: center;
  margin-bottom: 12px;
  font-size: 12px;
  flex-wrap: wrap;
}
.memory-check input {
  width: 290px;
  max-width: 100%;
  padding: 7px 9px;
  border: 1px solid #d4d6d0;
  border-radius: 2px;
}
#memoryCheckResult {
  color: #63685a;
  font-size: 12px;
}
.storage-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.storecard {
  min-width: 0;
  border: 1px solid #dedfdb;
  background: var(--paper);
  border-radius: 2px;
  padding: 13px;
}
.storecard header {
  display: flex;
  gap: 12px;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}
.storecard h2 {
  font-size: 15px;
  margin: 0;
}
.storecard header span {
  font-size: 12px;
  color: #63685a;
}
.storage-path {
  display: block;
  font-size: 12px;
  overflow-wrap: anywhere;
  color: #63685a;
  line-height: 1.8;
  margin-bottom: 8px;
}
.stored-turn {
  border-top: 1px solid #e8e9e5;
}
.stored-turn summary {
  display: flex;
  gap: 10px;
  align-items: center;
  cursor: pointer;
  padding: 7px 0;
  font-size: 12px;
}
.stored-turn summary b {
  color: #63685a;
  font: 11px var(--mono);
}
.stored-turn summary span {
  flex: 1;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.stored-turn summary code {
  max-width: 80px;
  overflow: hidden;
  font-size: 12px;
  color: #63685a;
}
.storecard pre {
  font: 11px/1.8 var(--mono);
  padding: 10px;
  background: #f8f8f8;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  max-height: 320px;
  overflow: auto;
  border-radius: 2px;
}
.storecard details > summary {
  font-size: 12px;
  cursor: pointer;
  margin: 10px 0;
}
.storecard dl {
  display: grid;
  grid-template-columns: 1fr 1fr;
  font-size: 12px;
  line-height: 2;
}
.storecard dt {
  color: #63685a;
}
.storecard dd {
  margin: 0;
  text-align: right;
}
.stored-summary {
  font-size: 13px;
  line-height: 1.9;
  white-space: pre-wrap;
  margin: 12px 0 17px;
}
@media (max-width: 800px) {
  .storage-grid {
    grid-template-columns: 1fr;
  }
  .memory-session {
    flex-wrap: wrap;
  }
  .memory-session > span {
    flex-basis: 100%;
  }
  .storecard {
    padding: 13px;
  }
}
@media (prefers-reduced-motion: no-preference) {
  .arch-pulse:not(.hidden) {
    animation: packet-arrival 0.75s ease-out both;
  }
  @keyframes packet-arrival {
    0% {
      opacity: 0;
    }
    25% {
      opacity: 1;
    }
    100% {
      opacity: 0;
    }
  }
}
#journeyView .composer {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 235px 118px;
  grid-template-rows: 23px 36px;
  gap: 2px 12px;
}
#journeyView .composer > label {
  grid-column: 1;
  grid-row: 1;
  align-self: center;
}
#journeyView .composer textarea {
  grid-column: 1;
  grid-row: 2;
  min-height: 35px;
  height: 35px;
  padding: 3px 0;
}
#journeyView .composer .modebar {
  grid-column: 2;
  grid-row: 1;
  float: none;
  font-size: 12px;
}
#journeyView .composer .modebar label {
  font-size: 12px;
}
#journeyView .composer .modebar select {
  max-width: 190px;
}
#journeyView .composer-bottom {
  display: contents;
}
#journeyView .composer-bottom .check {
  grid-column: 2;
  grid-row: 2;
  font-size: 12px;
}
#journeyView .composer-bottom .primary {
  grid-column: 3;
  grid-row: 1 / 3;
  align-self: stretch;
}
#journeyView .draftinfo {
  display: none;
}
.run-options {
  display: flex;
  gap: 8px;
  min-height: 28px;
  position: relative;
}
#journeyView.focus .run-options,
#journeyView.focus .composer {
  display: none;
}
#journeyView .run-options .configuration {
  flex: 1;
}
#journeyView .run-options .configuration[open] {
  top: 30px;
}
#journeyView .examples {
  display: block;
  position: relative;
}
#journeyView .examples summary {
  padding: 6px 12px;
  background: var(--paper);
  border: 1px solid #dddeda;
  border-radius: 2px;
  cursor: pointer;
  font-size: 12px;
}
.examplebuttons {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px;
  position: absolute;
  left: 0;
  top: 32px;
  padding: 9px;
  width: 330px;
  background: var(--paper);
  z-index: 30;
  border: 1px solid #d5d7d0;
  box-shadow: 0 8px 25px #3e413920;
  border-radius: 2px;
}
.examplebuttons button {
  text-align: left;
  background: #f8f8f7;
  border: 1px solid #e8e9e6;
}
@media (max-width: 800px) {
  #journeyView .composer {
    grid-template-columns: minmax(0, 1fr) 96px;
    grid-template-rows: 27px 38px 28px;
  }
  #journeyView .composer .modebar {
    grid-column: 1;
    grid-row: 1;
  }
  #journeyView .composer textarea {
    grid-column: 1;
    grid-row: 2;
  }
  #journeyView .composer-bottom .check {
    grid-column: 1;
    grid-row: 3;
    font-size: 12px;
  }
  #journeyView .composer-bottom .primary {
    grid-column: 2;
    grid-row: 1 / 4;
  }
  .examplebuttons {
    width: 270px;
  }
}

.resumebanner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 8px;
  padding: 10px 14px;
  border: 1px solid #e2e4df;
  border-radius: 2px;
  background: var(--soft);
}
.resumebanner strong {
  display: block;
  font-size: 13px;
}
.resumebanner small {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}
.resumeactions {
  display: flex;
  flex: none;
  align-items: center;
  gap: 10px;
}
.resumeactions label {
  font-size: 12px;
  color: var(--muted);
}
.resumeactions input {
  width: 52px;
  margin-left: 4px;
  padding: 4px 6px;
  border: 1px solid #d9dbd6;
  border-radius: 2px;
}
.sizemeter {
  display: block;
  width: 100%;
  height: 8px;
  margin: 0 0 12px;
  overflow: hidden;
  border: 0;
  border-radius: 2px;
  background: var(--line);
  appearance: none;
}
.sizemeter::-webkit-progress-bar {
  background: var(--line);
}
.sizemeter::-webkit-progress-value {
  background: var(--accent);
}
.sizemeter::-moz-progress-bar {
  background: var(--accent);
}
.sizemeter.over::-webkit-progress-value {
  background: #b8712b;
}
.sizemeter.over::-moz-progress-bar {
  background: #b8712b;
}
@media (max-width: 720px) {
  .resumebanner {
    align-items: stretch;
    flex-direction: column;
  }
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.toolgroups {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 14px;
}
.toolgroup {
  display: flex;
  align-items: center;
  gap: 2px;
}
.toolgroup + .toolgroup {
  padding-left: 14px;
  border-left: 1px solid var(--line);
}
.agentfocuslabel {
  font-size: 12px;
  color: var(--muted);
  margin-left: auto;
}
.agentfocuslabel:has(+ .hidden) {
  display: none;
}
.samplelist {
  margin: 0 8px 14px;
}
.samplelist summary {
  padding: 4px 0;
  cursor: pointer;
  font-size: 12px;
  color: #63685a;
}
.samplelist summary span {
  float: right;
}
.shortcuts {
  display: grid;
  grid-template-columns: max-content 1fr;
  gap: 6px 16px;
  font-size: 13px;
}
.shortcuts dt {
  font: 12px var(--mono);
}
.shortcuts dd {
  margin: 0;
  color: var(--muted);
}
.lesson-active #sampleBanner,
.lesson-active #requestSummary {
  display: none !important;
}
.coachbody h2 {
  margin: 8px 0 4px;
  font-size: 16px;
  letter-spacing: -0.2px;
}
.coachbody p {
  margin: 0;
  font-size: 14px;
  line-height: 1.65;
}
.coachbody code,
.lessonrun code {
  padding: 0 4px;
  border-radius: 2px;
  background: var(--soft);
  font: 12.5px var(--mono);
}
.coachbody .coachlook {
  margin-top: 4px;
  color: var(--muted);
  font-size: 13px;
}
.coachbody .coachowner {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
  color: var(--muted);
  font-size: 12px;
}
.coachtake {
  margin-top: 10px;
  padding: 10px 12px;
  border-radius: 2px;
  background: var(--soft);
}
.coachtake strong {
  display: block;
  margin-top: 8px;
  font-size: 12px;
  color: var(--accent);
}
.coachtake strong:first-child {
  margin-top: 0;
}
.coachtake button {
  margin-top: 8px;
}
.coach footer {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
}
.coachdetail {
  display: none;
}
.samplenote {
  margin: 0 0 10px;
  padding: 8px 12px;
  border-radius: 2px;
  background: #fdfaf2;
  color: #624819;
  font-size: 13px;
  line-height: 1.6;
}
.samplenote code {
  font: 12.5px var(--mono);
}

.demolink,
.feedbacklink {
  text-decoration: none;
  white-space: nowrap;
}
.coachask {
  display: inline-block;
  margin-top: 10px;
  color: var(--muted);
  font-size: 12.5px;
}
.lessonlink {
  display: inline-block;
  margin-top: 10px;
  padding: 7px 12px;
  text-decoration: none;
}
.demoonly,
body.demo .localonly,
body.demo #export,
body.demo #bodySearch,
body.demo #bodySearchKind,
body.demo #newSession {
  display: none;
}

/* ──────────────────────────────────────────────────────────
   화면 틀. 구조도 칸의 크기는 창 크기로만 정해진다.
   강의 글·상세·단계 목록은 오른쪽 칸 안에서만 늘고 줄어든다.
   ────────────────────────────────────────────────────────── */
:root {
  --appbar: 48px;
  --rail: clamp(300px, 31vw, 460px);
  font-size: 14px;
}
body {
  overflow: hidden;
  background: var(--bg);
}
.glyph {
  display: block;
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: square;
}
.glyph.solid {
  fill: currentColor;
  stroke: none;
}
.icon {
  display: inline-grid;
  place-items: center;
  flex: none;
  width: 32px;
  height: 32px;
  color: var(--ink);
}
.appbar {
  position: relative;
  z-index: 30;
  height: var(--appbar);
  padding: 0 10px;
  gap: 6px;
  background: var(--paper);
  border-bottom: 1px solid var(--line);
}
.brand {
  flex: none;
  gap: 8px;
  margin: 0 14px 0 2px;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.brandmark {
  display: block;
  width: 20px;
  height: 20px;
  color: var(--ink);
  background: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
}
.brandpoint {
  fill: var(--signal);
  stroke: none;
}
.mainnav {
  display: flex;
  flex: none;
  gap: 0;
  align-self: stretch;
  margin: 0;
}
.mainnav button {
  position: relative;
  align-items: center;
  padding: 0 11px;
  border-radius: 0;
  color: var(--muted);
  font-size: 13px;
  white-space: nowrap;
}
.mainnav button:hover {
  color: var(--ink);
}
.mainnav button.active {
  background: none;
  color: var(--ink);
  font-weight: 650;
}
.mainnav button.active::after {
  content: "";
  position: absolute;
  left: 11px;
  right: 11px;
  bottom: -1px;
  height: 2px;
  background: var(--ink);
}
.connection {
  flex: none;
  margin-left: auto;
  white-space: nowrap;
}
.connection i {
  border-radius: 0;
}
.appbar > .quiet {
  flex: none;
  padding: 6px 8px;
  font-size: 12px;
  white-space: nowrap;
}
.activitybar {
  flex: 0 1 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: 12px;
  padding: 0;
  color: var(--ink);
  font-size: 12px;
}
.activity-dot {
  width: 8px;
  height: 8px;
  border-radius: 0;
  background: var(--signal);
}
.activitybar button {
  padding: 3px 8px;
  background: none;
  border: 1px solid var(--line);
}
.layout {
  height: calc(100dvh - var(--appbar));
  grid-template-columns: minmax(0, 1fr) !important;
  max-width: none;
  align-items: stretch;
}
.main {
  min-width: 0;
  height: 100%;
  overflow: auto;
  padding: 0 18px 24px;
  max-width: none !important;
}
.layout.reading .main {
  padding: 0 max(24px, calc((100% - 1040px) / 2)) 64px;
}
.workspacebar {
  display: none;
}

/* 기록·파일 서랍 */
.project {
  display: none;
  position: fixed;
  left: 0;
  top: var(--appbar);
  width: min(320px, 88vw);
  height: calc(100dvh - var(--appbar));
  z-index: 45;
  padding: 10px 10px 14px;
  background: var(--paper);
  border-right: 1px solid var(--line);
  flex-direction: column;
}
.project.open {
  display: flex;
  box-shadow: 0 0 0 100vmax #0b0d0c47;
}
body:has(.project.open) .main {
  pointer-events: none;
}
.project-title {
  padding: 2px 4px 10px 10px;
}
.project-title strong {
  font-size: 13px;
}

/* 작업 영역: 왼쪽 구조도 칸 + 오른쪽 설명 칸 */
.diagram-layout .main {
  overflow: hidden;
  padding: 0;
}
#journeyView {
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) var(--rail);
  grid-template-rows: minmax(0, 1fr);
}
#journeyView .execution {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: var(--stage);
}
.execution > .sectionbar {
  flex: none;
  flex-wrap: nowrap;
  gap: 10px;
  height: 42px;
  margin: 0;
  padding: 0 8px 0 14px;
  background: var(--paper);
  border-bottom: 1px solid var(--line);
  overflow: hidden;
}
.execution .sectionbar h2 {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 650;
  white-space: nowrap;
}
.execution .sectionbar > div {
  display: flex;
  align-items: center;
  gap: 3px;
}
.execution .sectionbar .toolgroups {
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.execution .sectionbar .toolgroup {
  flex: none;
}
.execution .sectionbar button {
  padding: 5px 7px;
  font-size: 12px;
  white-space: nowrap;
}
.diagram-caption {
  flex: none;
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  height: 30px;
  padding: 0 14px;
  background: var(--stage);
  border-bottom: 1px solid var(--stage-line);
  color: var(--stage-muted);
  font-size: 12px;
}
.diagram-caption > span:first-child {
  color: var(--stage-ink);
  font-family: var(--mono);
  font-size: 11.5px;
}
.diagram-caption label {
  color: var(--stage-muted);
}
.diagram-caption select {
  max-width: 180px;
  padding: 2px 4px;
  color: var(--stage-ink);
  background: var(--stage-2);
  border: 1px solid var(--stage-line);
  font-size: 12px;
}
.stagelegend {
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}
.stagelegend b {
  width: 9px;
  height: 9px;
  background: var(--signal);
}
.stagelegend i {
  width: 18px;
  height: 2px;
  margin-left: 10px;
  background: var(--signal-dim);
}

/* 구조도 */
.architecture {
  flex: 1 1 0;
  min-height: 0;
  position: relative;
  overflow: hidden;
  background-color: var(--stage);
  background-image: radial-gradient(circle at 1px 1px, #ffffff14 1px, transparent 0);
  background-size: 22px 22px;
}
.architecture > svg {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  user-select: none;
}
.arch-group rect {
  fill: #ffffff06;
  stroke: var(--stage-line);
  stroke-width: 1;
}
.group-title {
  font-size: 13px;
  font-weight: 600;
  fill: #b9bfb7;
}
.group-sub {
  font: 10.5px var(--mono);
  fill: #7b827b;
}
.arch-edges path {
  stroke: #4a514c;
  stroke-width: 1.1;
}
.arch-edges path.visited {
  stroke: var(--signal-dim);
  stroke-width: 1.5;
}
.arch-edges path.current {
  stroke: var(--signal);
  stroke-width: 2.4;
  stroke-dasharray: 8 5;
  animation: arch-flow 0.65s linear infinite;
}
@keyframes arch-flow {
  to {
    stroke-dashoffset: -13;
  }
}
#arch-arrow path {
  stroke: #666d68;
}
#arch-seen-arrow path {
  stroke: var(--signal-dim);
}
#arch-hot-arrow path {
  stroke: var(--signal);
}
marker path {
  fill: none;
  stroke-width: 1.3;
}
.arch-node {
  cursor: pointer;
  outline: none;
}
.node-box {
  fill: #181c1a;
  stroke: #3e4540;
  stroke-width: 1;
  transition:
    fill 0.12s,
    stroke 0.12s;
}
.node-pip {
  fill: #303632;
}
.arch-node:hover .node-box {
  fill: #212623;
  stroke: #79817a;
}
.arch-node:focus-visible .node-box {
  stroke: var(--signal);
  stroke-width: 2;
}
.arch-node .node-title {
  font-size: 15px;
  font-weight: 600;
  fill: var(--stage-ink);
}
.arch-node .node-meta {
  font: 11px var(--mono);
  fill: var(--stage-muted);
}
.model-stage {
  font: 10.5px var(--mono);
  fill: #7b827b;
}
.arch-node.visited .node-box {
  stroke: var(--signal-dim);
}
.arch-node.visited .node-pip {
  fill: var(--signal-dim);
}
.arch-node.related .node-box {
  fill: #261f0e;
  stroke: var(--signal);
  stroke-width: 1.4;
}
.arch-node.current .node-box {
  fill: var(--signal);
  stroke: var(--signal);
}
.arch-node.current .node-pip {
  fill: #141512;
}
.arch-node.current .node-title {
  fill: #141512;
}
.arch-node.current .node-meta {
  fill: #443305;
  font-weight: 600;
}
.arch-node.unavailable .node-box {
  fill: none;
  stroke: #333a35;
  stroke-dasharray: 3 3;
}
.arch-node.unavailable .node-pip {
  fill: none;
}
.arch-node.unavailable .node-title,
.arch-node.unavailable .node-meta {
  fill: #747b74;
}
.arch-compact .arch-node .node-title {
  font-size: 17px;
}
.arch-compact .arch-node:not(.current) .node-meta,
.arch-compact .model-stage,
.arch-compact .group-sub {
  display: none;
}
.arch-pulse {
  pointer-events: none;
}
.arch-pulse circle {
  fill: var(--signal);
  stroke: var(--stage);
  stroke-width: 2;
}

/* 구조도 아래 읽음판과 재생 막대 */
.currentstep {
  flex: none;
  height: 64px;
  padding: 8px 14px;
  overflow: hidden;
  background: var(--stage-2);
  border: 0;
  border-top: 1px solid var(--stage-line);
  border-radius: 0;
  color: var(--stage-ink);
  font-size: 12px;
}
.currentstep > span {
  color: var(--stage-muted);
}
.stepheading strong {
  color: var(--stage-ink);
  font-size: 13px;
}
.stepnumber {
  color: var(--signal);
}
.stepheading .quiet {
  color: var(--stage-muted);
}
.stepheading .quiet:hover {
  background: #ffffff14;
}
.steptransfer small {
  color: var(--stage-muted);
}
.steptransfer span {
  color: #c9cec6;
}
.steptransfer b {
  color: var(--signal);
}
.execution .replay {
  flex: none;
  display: flex;
  align-items: center;
  gap: 2px;
  height: 44px;
  margin: 0;
  padding: 0 8px;
  background: var(--stage-2);
  border: 0;
  border-top: 1px solid var(--stage-line);
  border-radius: 0;
}
.replay > button {
  display: inline-grid;
  place-items: center;
  flex: none;
  min-width: 30px;
  height: 30px;
  padding: 0 6px;
  background: none;
  border: 0;
  color: var(--stage-ink);
  font-size: 12px;
}
.replay > button:hover {
  background: #ffffff14;
}
.replay > button:focus-visible {
  outline-color: var(--signal);
}
#play .when-playing,
#play.playing .when-stopped {
  display: none;
}
#play.playing .when-playing {
  display: block;
}
#scrubber {
  flex: 1 1 0;
  min-width: 40px;
  height: 22px;
  margin: 0 8px;
  appearance: none;
  background: transparent;
  cursor: pointer;
}
#scrubber::-webkit-slider-runnable-track {
  height: 2px;
  background: #414843;
}
#scrubber::-moz-range-track {
  height: 2px;
  background: #414843;
}
#scrubber::-webkit-slider-thumb {
  appearance: none;
  width: 4px;
  height: 18px;
  margin-top: -8px;
  border: 0;
  border-radius: 0;
  background: var(--signal);
}
#scrubber::-moz-range-thumb {
  width: 4px;
  height: 18px;
  border: 0;
  border-radius: 0;
  background: var(--signal);
}
#position {
  flex: none;
  padding: 0 6px;
  color: var(--stage-muted);
  font: 12px var(--mono);
  white-space: nowrap;
}
#live {
  color: var(--stage-muted);
}
/* 단계 실행 단추는 구조도 위에 띄워 칸의 크기를 바꾸지 않는다. */
.execution .controls {
  position: absolute;
  left: 50%;
  bottom: 118px;
  z-index: 5;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0;
  padding: 6px 10px;
  background: var(--paper);
  border: 1px solid var(--line);
  font-size: 12px;
  white-space: nowrap;
}

/* 오른쪽 칸 */
.rail {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  background: var(--panel);
  border-left: 1px solid var(--line);
}
.rail > * {
  flex: none;
}
.rail > .inspector {
  display: none;
  position: static;
  width: auto;
  height: auto;
  border: 0;
  box-shadow: none;
}
.rail > .inspector.open {
  display: block !important;
  flex: 1 1 0;
  min-height: 280px;
  overflow: auto;
  border-top: 1px solid var(--line);
}
.rail:has(.inspector.open) > :is(#promptForm, .run-options) {
  display: none;
}
#journeyView .rail .composer {
  position: relative;
  margin: 0;
  padding: 8px 16px 12px;
  background: none;
  border: 0;
  border-radius: 0;
}
#journeyView .rail .composer textarea {
  height: 84px;
  padding: 8px;
  background: var(--paper);
  border: 1px solid var(--line);
}
#journeyView .draftinfo {
  position: static;
  margin-top: 4px;
}
#journeyView .rail .modebar {
  float: none;
  margin-bottom: 8px;
}
#journeyView .rail .samplenote {
  margin: 0 0 10px;
  padding: 0;
  background: none;
  border: 0;
  color: var(--muted);
  font-size: 12.5px;
}
#journeyView .run-options {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 0 16px 16px;
}
#journeyView .configuration {
  margin: 0;
  border: 0;
  border-top: 1px solid var(--line);
  background: none;
}
#journeyView .configuration[open] {
  position: static;
  width: auto;
  max-height: none;
  box-shadow: none;
}
#journeyView .configuration summary {
  padding: 9px 0;
}
.recordtray {
  display: none;
  flex: 1 1 0 !important;
  min-height: 240px;
  overflow: auto;
  background: var(--paper);
  border-top: 1px solid var(--line);
}
#journeyView.focus .execution.records-open ~ .rail .recordtray {
  display: block;
}
.rail:has(.inspector.open) .recordtray {
  display: none !important;
}
#journeyView .samplebanner {
  margin: 0;
  padding: 8px 16px;
  background: none;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  color: var(--muted);
  font-size: 12px;
}
#journeyView .requestsummary {
  margin: 0;
  padding: 10px 16px;
  background: var(--paper);
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
}

/* 강의 안내 */
.coach {
  flex: 0 1 auto !important;
  display: flex;
  flex-direction: column;
  min-height: 0;
  max-height: 60%;
  padding: 14px 18px 12px;
  background: var(--paper);
  border: 0;
  border-radius: 0;
}
.rail:not(:has(.inspector.open)) > .coach {
  max-height: none;
}
.coach header {
  flex: none;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  grid-template-areas:
    "name list exit"
    "dots dots dots"
    "source source count";
  align-items: center;
  gap: 5px 4px;
  font-size: 12px;
  color: var(--muted);
}
.coach header [data-coach="list"] {
  grid-area: list;
}
.coach header [data-coach="exit"] {
  grid-area: exit;
  width: 28px;
  height: 28px;
}
.coach header small {
  grid-area: count;
  font: 12px var(--mono);
}
.coachname {
  grid-area: name;
  min-width: 0;
  overflow: hidden;
  color: var(--ink);
  font-size: 13px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.coachname b {
  margin-right: 8px;
  color: var(--signal-ink);
  font: 650 12px var(--mono);
}
.coachdots {
  grid-area: dots;
  display: flex;
  gap: 3px;
}
.coachdots i {
  flex: 1;
  height: 3px;
  border-radius: 0;
  background: var(--line);
}
.coachdots i.done {
  background: #8d928e;
}
.coachdots i.current {
  background: var(--ink);
}
.coachsource {
  grid-area: source;
  margin: 0;
  color: var(--muted);
}
.coachbody {
  flex: 1 1 auto;
  min-height: 0;
  max-height: none;
  overflow: auto;
}
.coach footer {
  flex: none;
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
}
.coachbody h2 {
  margin: 12px 0 6px;
  font-size: 18px;
  font-weight: 650;
  line-height: 1.4;
  letter-spacing: -0.012em;
}
.coachbody p {
  font-size: 14px;
  line-height: 1.72;
}

/* 누가 정했나: 색띠 대신 모양과 글자로 구분한다. */
.decision-kind,
.decision-kind[data-owner] {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  padding: 0;
  background: none;
  color: var(--ink);
  font-size: 12px;
  font-weight: 650;
}
.decision-kind::before {
  content: "";
  flex: none;
  width: 8px;
  height: 8px;
  background: var(--ink);
}
.decision-kind[data-owner="model"]::before {
  border-radius: 50%;
  background: #d98e00;
}
.decision-kind[data-owner="config"]::before {
  transform: rotate(45deg) scale(0.86);
  background: #4f7a3a;
}
.decision-kind[data-owner="user"]::before {
  clip-path: polygon(50% 0, 100% 100%, 0 100%);
  background: #1f7a74;
}
.decision-kind[data-owner="runtime"]::before {
  background: none;
  box-shadow: inset 0 0 0 2px #46546a;
}
.decision-kind[data-owner="external"]::before {
  border-radius: 50%;
  background: none;
  box-shadow: inset 0 0 0 2px #7a4b6a;
}
.evidence-kind {
  margin: 0 0 0 8px;
  padding: 0;
  background: none;
  color: var(--muted);
}

/* 창이 좁을 때 */
@media (max-width: 1180px) {
  .connection span,
  .demolink {
    display: none;
  }
}
@media (max-width: 960px) {
  .feedbacklink {
    display: none;
  }
}
@media (max-width: 799px) {
  :root {
    --appbar: 88px;
  }
  .appbar {
    flex-wrap: wrap;
    gap: 0 6px;
    align-content: flex-start;
  }
  .appbar > #menu,
  .appbar > .brand,
  .appbar > .connection,
  .appbar > #help {
    height: 47px;
  }
  .connection span {
    display: inline;
  }
  .mainnav {
    order: 9;
    flex: 0 0 calc(100% + 20px);
    height: 40px;
    margin: 0 -10px;
    padding: 0 4px;
    overflow-x: auto;
    border-top: 1px solid var(--line);
    scrollbar-width: none;
  }
  .activitybar {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 35;
    height: 44px;
    margin: 0;
    padding: 0 10px;
    background: var(--paper);
    border-top: 1px solid var(--line);
  }
  .activitybar .activity-prompt {
    display: none;
  }
  .activitybar strong {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .diagram-layout .main {
    overflow: auto;
  }
  #journeyView {
    display: block;
    height: auto;
  }
  .execution > .sectionbar {
    padding-left: 10px;
  }
  .execution .sectionbar h2 {
    display: none;
  }
  .diagram-caption {
    display: none;
  }
  .architecture {
    flex: none;
    height: clamp(220px, 34dvh, 420px);
  }
  .currentstep {
    height: 58px;
    padding: 6px 10px;
  }
  .replay > button {
    min-width: 40px;
    height: 40px;
  }
  #first,
  #live {
    display: none;
  }
  .rail {
    overflow: visible;
    border-left: 0;
  }
  .rail > .inspector.open {
    position: fixed;
    inset: var(--appbar) 0 0 0;
    z-index: 40;
    min-height: 0;
    background: var(--paper);
  }
  .coach {
    max-height: none;
  }
  .recordtray {
    flex: none !important;
    height: 360px;
  }
  .detailtabs {
    flex-wrap: nowrap;
    overflow-x: auto;
    scrollbar-width: none;
  }
  .detailtabs button {
    flex: none;
    white-space: nowrap;
  }
  .layout.reading .main {
    padding: 0 16px 48px;
  }
}
@media (max-width: 799px) and (min-height: 640px) {
  #journeyView .execution {
    position: sticky;
    top: 0;
    z-index: 10;
  }
}
@media (max-width: 480px) {
  .brand {
    margin-right: 0;
  }
  #help {
    width: 32px;
    padding: 0;
    font-size: 0;
  }
  #help::before {
    content: "?";
    font-size: 14px;
  }
  .connection {
    font-size: 11.5px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .arch-edges path.current {
    animation: none;
    stroke-dasharray: none;
  }
}

/* 상태·버튼 */
.status,
.status.running,
.status.paused,
.status.completed,
.status.failed {
  padding: 0;
  background: none;
  border-radius: 0;
  color: var(--muted);
  font: 12px var(--mono);
}
.status.running,
.status.paused {
  color: var(--signal-ink);
}
.status.completed {
  color: var(--green);
}
.status.failed {
  color: #a33a2a;
}
.secondary {
  border-color: var(--line);
}
.secondary:hover {
  border-color: var(--ink);
}
.quiet {
  color: var(--muted);
}
.quiet:hover,
.icon:hover {
  color: var(--ink);
  background: var(--soft);
}

/* 단계 목록 */
.recordtray .eventtoolbar {
  position: sticky;
  top: 0;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 6px;
  margin: 0;
  padding: 8px 10px;
  background: var(--paper);
  border-bottom: 1px solid var(--line);
}
.recordtray .eventtoolbar input,
.recordtray .eventtoolbar select {
  width: 100%;
  min-width: 0;
  height: 28px;
  margin: 0;
  padding: 0 8px;
  background: var(--panel);
  border: 1px solid var(--line);
  font-size: 12px;
}
.recordtray #decisionFocus {
  width: 118px;
}
.recordtray #eventCount {
  color: var(--muted);
  font: 11.5px var(--mono);
  white-space: nowrap;
}
.recordtray #bodySearch {
  grid-column: 1 / 3;
}
.recordtray #bodySearchKind {
  grid-column: 3;
  width: 92px;
}
.recordtray #timeline {
  padding: 0;
}
.chapter {
  margin: 0;
}
.recordtray .chapter > summary {
  position: sticky;
  top: 44px;
  z-index: 1;
  padding: 7px 10px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  font-size: 12.5px;
}
body:not(.demo) .recordtray .chapter > summary {
  top: 80px;
}
.chapter > summary .chaptericon {
  width: auto;
  height: auto;
  padding: 0;
  background: none;
  border-radius: 0;
  color: var(--signal-ink);
  font: 600 12px var(--mono);
}
.chapter > summary small {
  font: 11.5px var(--mono);
}
.recordtray .event {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-height: 34px;
  margin: 0;
  padding: 3px 10px;
  background: none;
  border: 0;
  border-bottom: 1px solid #ecede8;
  border-radius: 0;
  text-align: left;
}
.recordtray .event:hover {
  background: var(--soft);
}
.recordtray .event.selected {
  background: var(--signal);
  color: #141512;
}
.recordtray .event.selected:before {
  display: none;
}
.recordtray .event.selected :is(.eventtitle, .eventsub, .eventid, .actor) {
  color: #141512;
}
.recordtray .event.past {
  opacity: 1;
}
.recordtray .event.past .eventtitle {
  color: var(--muted);
}
.recordtray .event .actor {
  width: auto;
  height: auto;
  background: none;
  border: 0;
  border-radius: 0;
  color: var(--muted);
  font: 600 11px var(--mono);
  text-align: center;
}
.recordtray .eventtext {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}
.recordtray .event .eventtitle {
  flex: none;
  max-width: 62%;
  overflow: hidden;
  font-size: 12.5px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.recordtray .event .eventsub {
  min-width: 0;
  overflow: hidden;
  color: var(--muted);
  font: 11px var(--mono);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.recordtray .event .eventid {
  color: var(--muted);
  font: 11px var(--mono);
}

/* 상세 머리 */
.inspectbar {
  height: 44px;
  padding: 0 8px 0 16px;
  background: var(--paper);
}
.detailhead {
  padding: 16px 16px 10px;
}
.detailhead h2 {
  margin-top: 8px;
  font-size: 18px;
  font-weight: 650;
  letter-spacing: -0.012em;
}
.detailhead code {
  color: var(--muted);
  font: 12px var(--mono);
}
.detailhead .pill {
  padding: 0;
  border: 0;
  color: var(--muted);
}
.componentnav {
  margin: 0 16px 8px;
}
.detailtabs {
  padding: 0 16px;
}
.detailcontent {
  padding: 14px 16px 24px;
}

/* 재생 막대의 실행 리듬 */
.scrub {
  position: relative;
  flex: 1 1 0;
  min-width: 40px;
  height: 30px;
  margin: 0 8px;
}
#ribbon {
  position: absolute;
  inset: 3px 2px;
  width: calc(100% - 4px);
  height: 24px;
  pointer-events: none;
}
#ribbon path {
  fill: none;
  stroke-width: 1px;
  vector-effect: non-scaling-stroke;
}
#ribbon .all .model {
  stroke: #79807a;
}
#ribbon .all .tool {
  stroke: #5a615c;
}
#ribbon .all .other {
  stroke: #3b423d;
}
#ribbon .played .model {
  stroke: var(--signal);
}
#ribbon .played .tool {
  stroke: #cf9416;
}
#ribbon .played .other {
  stroke: var(--signal-dim);
}
.scrub #scrubber {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
}
.scrub #scrubber::-webkit-slider-runnable-track {
  height: 30px;
  background: transparent;
}
.scrub #scrubber::-moz-range-track {
  height: 30px;
  background: transparent;
}
.scrub #scrubber::-webkit-slider-thumb {
  width: 3px;
  height: 30px;
  margin-top: 0;
}
.scrub #scrubber::-moz-range-thumb {
  width: 3px;
  height: 30px;
}
/* 강의 중에는 강의의 진행만 번호로 보여 준다. */
.lesson-active .stepnumber,
.lesson-active #position {
  display: none;
}

/* 배우기 */
.lessons {
  max-width: 1040px;
  margin: 0 auto;
  padding: 44px 0 24px;
}
.lessonhero h1 {
  max-width: 18em;
  font-size: 34px;
  font-weight: 750;
  line-height: 1.28;
  letter-spacing: -0.025em;
  text-wrap: balance;
}
.lessonhero p {
  max-width: 40em;
  margin-top: 12px;
  color: var(--muted);
  font-size: 15px;
  line-height: 1.75;
}
.lessonactions {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 20px;
  color: var(--muted);
  font-size: 13px;
}
.lessonactions .primary {
  padding: 11px 18px;
  font-size: 14px;
}
.heroflow {
  position: relative;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0;
  margin: 32px 0 0;
  padding: 24px 22px 22px;
  overflow: hidden;
  list-style: none;
  background-color: var(--stage);
  background-image: radial-gradient(circle at 1px 1px, #ffffff14 1px, transparent 0);
  background-size: 22px 22px;
}
.heroflow::before {
  content: "";
  position: absolute;
  left: 22px;
  right: 22px;
  top: 30px;
  height: 1px;
  background: var(--signal-dim);
}
.heroflow::after {
  content: "";
  position: absolute;
  top: 27px;
  left: 22px;
  width: 7px;
  height: 7px;
  background: var(--signal);
  animation: hero-travel 7s linear infinite;
}
@keyframes hero-travel {
  to {
    left: calc(100% - 29px);
  }
}
.heroflow li {
  position: relative;
  padding: 22px 12px 0 0;
  color: var(--stage-ink);
  font-size: 14px;
  font-weight: 650;
}
.heroflow li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 1px;
  width: 11px;
  height: 11px;
  background: var(--stage);
  border: 1px solid var(--signal);
}
.heroflow .decision-kind,
.heroflow .decision-kind[data-owner] {
  display: flex;
  margin-top: 4px;
  color: var(--stage-muted);
  font-size: 12px;
  font-weight: 500;
}
.heroflow .decision-kind::before {
  background: var(--stage-ink);
}
.heroflow .decision-kind[data-owner="model"]::before {
  background: var(--signal);
}
.heroflow .decision-kind[data-owner="config"]::before {
  background: #8fbf73;
}
.heroflow .decision-kind[data-owner="user"]::before {
  background: #62c4bd;
}
.ownerlegend,
.lessonrun {
  margin: 40px 0 0;
  padding: 14px 0 0;
  background: none;
  border: 0;
  border-top: 1px solid var(--ink);
  border-radius: 0;
}
.ownerlegend h2,
.lessonrun h2 {
  font-size: 17px;
  font-weight: 650;
}
.ownerlegend > p,
.lessonrun p {
  margin-top: 4px;
  color: var(--muted);
  font-size: 13px;
}
.ownerlegend > div {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px 28px;
  margin-top: 14px;
}
.ownerlegend article {
  display: grid;
  gap: 2px;
}
.ownerlegend small {
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.6;
}
.lessonrun button,
.lessonrun .lessonlink {
  margin-top: 10px;
}
.lessonlink {
  display: inline-block;
  padding: 7px 12px;
  text-decoration: none;
}
.lessonchapter {
  display: grid;
  grid-template-columns: 232px minmax(0, 1fr);
  grid-template-rows: auto 1fr;
  gap: 0 32px;
  margin-top: 40px;
  padding-top: 14px;
  border-top: 1px solid var(--ink);
}
.lessonchapter h2 {
  grid-column: 1;
  font-size: 17px;
  font-weight: 650;
  line-height: 1.4;
}
.lessonchapter h2 small {
  display: block;
  margin-bottom: 4px;
  color: var(--signal-ink);
  font: 600 12px var(--mono);
}
.lessonchapter > p {
  grid-column: 1;
  margin-top: 6px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.6;
}
.lessonchapter > div {
  grid-column: 2;
  grid-row: 1 / 3;
  margin-top: -6px;
}
.lessoncard {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 0 6px;
  width: 100%;
  padding: 12px 0;
  background: none;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  text-align: left;
}
.lessonchapter > div .lessoncard:last-child {
  border-bottom: 0;
}
.lessoncard:hover {
  background: none;
}
.lessoncard:hover strong {
  text-decoration: underline;
  text-underline-offset: 3px;
}
.lessoncard b {
  display: block;
  width: auto;
  height: auto;
  background: none;
  border-radius: 0;
  color: var(--muted);
  font: 600 13px var(--mono);
}
.lessoncard.done b {
  background: none;
  color: var(--signal-ink);
}
.lessoncard strong {
  display: block;
  font-size: 15px;
  font-weight: 650;
}
.lessoncard small {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 13px;
}
.lessoncard i {
  color: var(--muted);
  font: 12px var(--mono);
  font-style: normal;
}
.lessonglossary {
  margin-top: 36px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}
.lessonglossary summary {
  cursor: pointer;
  font-size: 13px;
  font-weight: 650;
}
.lessonglossary dl {
  display: grid;
  grid-template-columns: minmax(120px, 200px) minmax(0, 1fr);
  gap: 8px 16px;
  margin: 12px 0 0;
  font-size: 13px;
  line-height: 1.6;
}
.lessonglossary dt {
  font-weight: 650;
}
.lessonglossary dd {
  margin: 0;
  color: var(--muted);
}
@media (max-width: 799px) {
  .lessons {
    padding-top: 24px;
  }
  .lessonhero h1 {
    font-size: 26px;
  }
  .heroflow {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    row-gap: 18px;
  }
  .heroflow::before,
  .heroflow::after {
    display: none;
  }
  .ownerlegend > div {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .lessonchapter {
    display: block;
  }
  .lessonchapter > div {
    margin-top: 8px;
  }
}
@media (max-width: 480px) {
  .heroflow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .ownerlegend > div {
    grid-template-columns: minmax(0, 1fr);
  }
  .lessonactions {
    flex-wrap: wrap;
  }
}
@media (prefers-reduced-motion: reduce) {
  .heroflow::after {
    display: none;
  }
}

/* 웹 데모 */
body.demo .demoonly {
  display: revert;
}
.demonote {
  margin: 16px 0 0;
  padding: 10px 0;
  border-top: 1px solid var(--ink);
  border-bottom: 1px solid var(--line);
  color: var(--ink);
  font-size: 13px;
  line-height: 1.6;
}
.demonote a {
  text-decoration: underline;
  text-underline-offset: 3px;
}
body.demo :is(#promptForm, .run-options, #editPrompt, #checkFile, #showDiff, #saveFile, #undoFile) {
  display: none !important;
}
body.demo .componentcard header .pill {
  display: none;
}

/* 한국어는 낱말 중간에서 줄을 바꾸지 않는다. 코드와 값은 그대로 둔다. */
body {
  word-break: keep-all;
  overflow-wrap: break-word;
}
:is(pre, code, textarea, .codeline) {
  word-break: normal;
  overflow-wrap: anywhere;
}
.arch-node.current.unavailable .node-box {
  fill: var(--signal);
  stroke: var(--signal);
  stroke-dasharray: none;
}
.arch-node.current.unavailable .node-title {
  fill: #141512;
}
.arch-node.current.unavailable .node-meta {
  fill: #443305;
}
.layout.reading .main > .view:not(#lessonsView) {
  padding-top: 26px;
}
.componentcards {
  gap: 0 32px;
}
.componentcard {
  padding: 14px 0 12px;
  background: none;
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
}
.componentcard header .pill {
  padding: 0;
  border: 0;
  font: 11.5px var(--mono);
}
@media (max-width: 799px) {
  .toolgroup + .toolgroup {
    border-left: 0;
  }
  .execution .sectionbar .toolgroup:first-child,
  .execution .sectionbar .toolgroup:has(#newSession) {
    display: none;
  }
}
@media (max-width: 480px) {
  .brand {
    font-size: 14px;
    margin-left: 0;
  }
  .connection {
    font-size: 11px;
  }
  #help {
    margin-left: 2px;
  }
}

/* 오른쪽 칸의 입력란 */
#journeyView .rail .composer {
  display: block;
  padding-top: 14px;
}
.rail .composer > label[for="prompt"] {
  display: block;
  margin: 0 0 6px;
  font-size: 13px;
  font-weight: 650;
}
#journeyView .rail .modebar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 12px;
}
.rail .modebar label {
  flex: none;
  color: var(--muted);
  font-size: 12px;
}
.rail .modebar select {
  flex: 1;
  min-width: 0;
  height: 30px;
}
#journeyView .rail .composer textarea {
  display: block;
  width: 100%;
  resize: vertical;
}
#journeyView .rail .composer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-top: 10px;
}
.rail .examples {
  display: block;
  padding: 0;
  border-top: 1px solid var(--line);
}
.rail .examples > summary {
  padding: 9px 0;
  cursor: pointer;
  font-size: 13px;
  font-weight: 650;
}
.rail .examplebuttons {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding-bottom: 12px;
}
.rail .examplebuttons button {
  padding: 5px 8px;
  border: 1px solid var(--line);
  font-size: 12px;
}
.rail .examplebuttons button:hover {
  border-color: var(--ink);
}
.currentstep > strong {
  margin-right: 8px;
  color: var(--stage-ink);
  font-size: 13px;
}
